const app = {
  world: null,
  selectedId: null,
  draftLaws: {},
  rehearsal: null,
  busy: false,
  toastTimer: null,
  map: null,
};

const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];

const elements = {
  loadingVeil: $("#loadingVeil"),
  continuity: $("#continuityStatus"),
  continuityText: $("#continuityText"),
  cycle: $("#cycleValue"),
  mood: $("#worldMood"),
  revision: $("#revisionValue"),
  integrityDot: $("#integrityDot"),
  placeIndex: $("#placeIndex"),
  placeName: $("#placeName"),
  placeSelect: $("#placeSelect"),
  worldAnswer: $("#worldAnswer"),
  answerText: $("#answerText"),
  probeForm: $("#probeForm"),
  probeInput: $("#probeInput"),
  lawControls: $("#lawControls"),
  draftCount: $("#draftCount"),
  rehearseLaws: $("#rehearseLawsButton"),
  invariantList: $("#invariantList"),
  invariantCount: $("#invariantCount"),
  receiptList: $("#receiptList"),
  traceIntegrity: $("#traceIntegrity"),
  traceSummary: $("#traceSummary"),
  traceFooter: $("#traceFooter"),
  rehearsalDialog: $("#rehearsalDialog"),
  forecastChart: $("#forecastChart"),
  forecastDeltas: $("#forecastDeltas"),
  reading: $(".reading"),
  readingMark: $("#readingMark"),
  readingLabel: $("#readingLabel"),
  rehearsalReading: $("#rehearsalReading"),
  violationList: $("#violationList"),
  commitButton: $("#commitButton"),
  toast: $("#toast"),
};

const metricColors = {
  vitality: "#aabf95",
  moisture: "#8baeb1",
  diversity: "#c59261",
  kinship: "#b0a3bc",
};

function escapeHtml(value) {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function percent(value, signed = false) {
  const number = Number(value || 0) * 100;
  const prefix = signed && number > 0 ? "+" : "";
  return `${prefix}${Math.round(number)}%`;
}

function titleCase(value) {
  return String(value).replace(/(^|[-_\s])\w/g, (match) => match.toUpperCase()).replaceAll("-", " ");
}

async function api(path, options = {}) {
  const { allowRefusal = false, ...fetchOptions } = options;
  const response = await fetch(path, {
    headers: { "Content-Type": "application/json", ...(fetchOptions.headers || {}) },
    cache: "no-store",
    ...fetchOptions,
  });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok && !(allowRefusal && payload.accepted === false)) {
    const error = new Error(payload.error || `The world answered with ${response.status}.`);
    error.payload = payload;
    error.status = response.status;
    throw error;
  }
  return payload;
}

class WorldMap {
  constructor(canvas, onSelect) {
    this.canvas = canvas;
    this.context = canvas.getContext("2d");
    this.onSelect = onSelect;
    this.world = null;
    this.selectedId = null;
    this.hoveredId = null;
    this.points = [];
    this.reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    this.resizeObserver = new ResizeObserver(() => this.resize());
    this.resizeObserver.observe(canvas);
    canvas.addEventListener("pointermove", (event) => this.pointerMove(event));
    canvas.addEventListener("pointerleave", () => {
      this.hoveredId = null;
      canvas.style.cursor = "default";
    });
    canvas.addEventListener("click", (event) => this.pointerClick(event));
    canvas.addEventListener("keydown", (event) => this.keyDown(event));
    this.resize();
    requestAnimationFrame((time) => this.draw(time));
  }

  setWorld(world, selectedId) {
    this.world = world;
    this.selectedId = selectedId;
    this.layout();
  }

  resize() {
    const bounds = this.canvas.getBoundingClientRect();
    const ratio = Math.min(window.devicePixelRatio || 1, 2);
    this.width = Math.max(bounds.width, 1);
    this.height = Math.max(bounds.height, 1);
    this.canvas.width = Math.round(this.width * ratio);
    this.canvas.height = Math.round(this.height * ratio);
    this.context.setTransform(ratio, 0, 0, ratio, 0, 0);
    this.layout();
  }

  layout() {
    if (!this.world || !this.width) return;
    const side = Math.max(38, this.width * 0.055);
    const top = Math.max(62, this.height * 0.09);
    const bottom = Math.max(160, this.height * 0.23);
    this.points = this.world.cells.map((cell) => ({
      ...cell,
      px: side + cell.x * (this.width - side * 2),
      py: top + cell.y * (this.height - top - bottom),
    }));
  }

  pointerPosition(event) {
    const bounds = this.canvas.getBoundingClientRect();
    return { x: event.clientX - bounds.left, y: event.clientY - bounds.top };
  }

  nearest(event) {
    const pointer = this.pointerPosition(event);
    let nearest = null;
    let distance = 25;
    for (const point of this.points) {
      const candidate = Math.hypot(point.px - pointer.x, point.py - pointer.y);
      if (candidate < distance) {
        nearest = point;
        distance = candidate;
      }
    }
    return nearest;
  }

  pointerMove(event) {
    const nearest = this.nearest(event);
    this.hoveredId = nearest?.id || null;
    this.canvas.style.cursor = nearest ? "pointer" : "default";
  }

  pointerClick(event) {
    const nearest = this.nearest(event);
    if (nearest) this.onSelect(nearest.id);
  }

  keyDown(event) {
    if (!["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown"].includes(event.key)) return;
    event.preventDefault();
    const cells = this.world?.cells || [];
    const current = Math.max(0, cells.findIndex((cell) => cell.id === this.selectedId));
    const backwards = event.key === "ArrowLeft" || event.key === "ArrowUp";
    const next = (current + (backwards ? -1 : 1) + cells.length) % cells.length;
    this.onSelect(cells[next].id);
  }

  draw(time) {
    const context = this.context;
    context.clearRect(0, 0, this.width || 0, this.height || 0);
    if (this.world && this.points.length) {
      this.drawField(context, time);
      this.drawLinks(context);
      this.drawNodes(context, time);
    }
    requestAnimationFrame((nextTime) => this.draw(nextTime));
  }

  drawField(context, time) {
    const centerX = this.points.reduce((sum, point) => sum + point.px, 0) / this.points.length;
    const centerY = this.points.reduce((sum, point) => sum + point.py, 0) / this.points.length;
    const pulse = this.reducedMotion ? 0 : Math.sin(time / 4200) * 4;
    context.save();
    context.strokeStyle = "rgba(170, 191, 149, 0.035)";
    context.lineWidth = 1;
    for (const radius of [75, 150, 235]) {
      context.beginPath();
      context.arc(centerX, centerY, radius + pulse, 0, Math.PI * 2);
      context.stroke();
    }
    context.restore();
  }

  drawLinks(context) {
    const byId = new Map(this.points.map((point) => [point.id, point]));
    context.save();
    context.lineWidth = 0.7;
    for (const [leftId, rightId] of this.world.links) {
      const left = byId.get(leftId);
      const right = byId.get(rightId);
      if (!left || !right) continue;
      const touchesSelection = leftId === this.selectedId || rightId === this.selectedId;
      const kinship = (left.kinship + right.kinship) / 2;
      const alpha = touchesSelection ? 0.34 : 0.055 + kinship * 0.1;
      context.strokeStyle = `rgba(174, 195, 158, ${alpha})`;
      context.lineWidth = touchesSelection ? 1.15 : 0.7;
      context.beginPath();
      context.moveTo(left.px, left.py);
      const midX = (left.px + right.px) / 2;
      const midY = (left.py + right.py) / 2 - Math.abs(left.px - right.px) * 0.025;
      context.quadraticCurveTo(midX, midY, right.px, right.py);
      context.stroke();
    }
    context.restore();
  }

  drawNodes(context, time) {
    for (const point of this.points) {
      const selected = point.id === this.selectedId;
      const hovered = point.id === this.hoveredId;
      const phase = this.hash(point.id) % 5000;
      const breath = this.reducedMotion ? 0 : Math.sin((time + phase) / 1300) * 0.65;
      const radius = 3.1 + point.vitality * 3.7 + breath;
      const hue = 73 + point.diversity * 42 - point.moisture * 14;
      const lightness = 48 + point.vitality * 24;

      context.save();
      if (selected || hovered) {
        context.strokeStyle = selected ? "rgba(213, 225, 194, 0.6)" : "rgba(213, 225, 194, 0.3)";
        context.lineWidth = 1;
        context.beginPath();
        context.arc(point.px, point.py, radius + (selected ? 11 : 7), 0, Math.PI * 2);
        context.stroke();
      }

      const glow = context.createRadialGradient(point.px, point.py, 0, point.px, point.py, radius * 4.5);
      glow.addColorStop(0, `hsla(${hue}, 35%, ${lightness}%, ${selected ? 0.32 : 0.17})`);
      glow.addColorStop(1, `hsla(${hue}, 35%, ${lightness}%, 0)`);
      context.fillStyle = glow;
      context.beginPath();
      context.arc(point.px, point.py, radius * 4.5, 0, Math.PI * 2);
      context.fill();

      context.fillStyle = `hsla(${hue}, 34%, ${lightness}%, ${selected ? 1 : 0.82})`;
      context.beginPath();
      context.arc(point.px, point.py, radius, 0, Math.PI * 2);
      context.fill();
      context.strokeStyle = "rgba(235, 235, 216, 0.38)";
      context.lineWidth = 0.6;
      context.stroke();

      if (selected || hovered || this.width > 980) {
        context.font = `${selected ? 9 : 7}px ${getComputedStyle(document.documentElement).getPropertyValue("--sans")}`;
        context.textAlign = "center";
        context.fillStyle = selected ? "rgba(230, 231, 218, 0.86)" : "rgba(178, 184, 168, 0.38)";
        context.fillText(point.name.toUpperCase(), point.px, point.py + radius + (selected ? 19 : 15));
      }
      context.restore();
    }
  }

  hash(value) {
    let result = 0;
    for (let index = 0; index < value.length; index += 1) result = ((result << 5) - result + value.charCodeAt(index)) | 0;
    return Math.abs(result);
  }
}

function selectedCell() {
  return app.world?.cells.find((cell) => cell.id === app.selectedId) || app.world?.cells[0];
}

function setSelected(id) {
  if (!app.world?.cells.some((cell) => cell.id === id)) return;
  app.selectedId = id;
  app.map.setWorld(app.world, id);
  renderPlace();
}

function renderWorld({ preserveDraft = true } = {}) {
  if (!app.world) return;
  if (!app.selectedId || !app.world.cells.some((cell) => cell.id === app.selectedId)) {
    app.selectedId = app.world.metrics.weakest || app.world.cells[0].id;
  }
  if (!preserveDraft) app.draftLaws = {};

  elements.cycle.textContent = String(app.world.cycle).padStart(6, "0");
  elements.revision.textContent = `R${String(app.world.revision).padStart(4, "0")}`;
  elements.continuityText.textContent = `Present · ${Math.round(app.world.cycle_seconds / 60)}m cadence`;
  elements.continuity.classList.remove("is-offline");
  elements.integrityDot.classList.toggle("is-broken", !app.world.integrity.ok);
  elements.integrityDot.title = app.world.integrity.ok ? "Receipt chain intact" : "Continuity check failed";

  const tension = app.world.metrics.tension;
  const vitality = app.world.metrics.vitality;
  elements.mood.textContent = vitality < 0.38 ? "Holding the reserve" : tension > 0.13 ? "In productive tension" : tension < 0.045 ? "Quietly coherent" : "Listening";

  for (const metric of ["vitality", "moisture", "diversity", "kinship"]) {
    const container = $(`[data-metric="${metric}"]`, $("#metricsRibbon"));
    $("strong", container).textContent = percent(app.world.metrics[metric]);
    $("b", container).style.width = `${Math.max(0, Math.min(100, app.world.metrics[metric] * 100))}%`;
  }

  app.map.setWorld(app.world, app.selectedId);
  renderPlace();
  renderLaws();
  renderInvariants();
  renderTrace();
}

function renderPlace() {
  const cell = selectedCell();
  if (!cell) return;
  elements.placeIndex.textContent = String(app.world.cells.indexOf(cell) + 1).padStart(2, "0");
  elements.placeName.textContent = cell.name;

  const existingIds = [...elements.placeSelect.options].map((option) => option.value).join(",");
  const newIds = app.world.cells.map((place) => place.id).join(",");
  if (existingIds !== newIds) {
    elements.placeSelect.replaceChildren(...app.world.cells.map((place, index) => {
      const option = document.createElement("option");
      option.value = place.id;
      option.textContent = `${String(index + 1).padStart(2, "0")} · ${place.name}`;
      return option;
    }));
  }
  elements.placeSelect.value = cell.id;

  for (const measure of ["vitality", "moisture", "diversity", "kinship"]) {
    const row = $(`[data-measure="${measure}"]`, $("#placeMeasures"));
    $("strong", row).textContent = percent(cell[measure]);
    $("b", row).style.width = `${cell[measure] * 100}%`;
    $("b", row).style.background = metricColors[measure];
  }
}

function setRangeAppearance(input) {
  const minimum = Number(input.min);
  const maximum = Number(input.max);
  const fill = ((Number(input.value) - minimum) / (maximum - minimum)) * 100;
  input.style.setProperty("--range-fill", `${fill}%`);
}

function renderLaws() {
  for (const label of $$(".law", elements.lawControls)) {
    const law = label.dataset.law;
    const input = $("input", label);
    const shown = Object.hasOwn(app.draftLaws, law) ? app.draftLaws[law] : app.world.laws[law];
    input.value = shown;
    $("output", label).textContent = percent(shown);
    label.classList.toggle("is-changed", Object.hasOwn(app.draftLaws, law));
    setRangeAppearance(input);
  }
  const count = Object.keys(app.draftLaws).length;
  elements.draftCount.textContent = count ? `${count} ${count === 1 ? "change" : "changes"} held` : "No changes held";
  elements.rehearseLaws.disabled = count === 0 || app.busy;
}

function renderInvariants() {
  elements.invariantCount.textContent = `${app.world.invariants.length} standing`;
  elements.invariantList.innerHTML = app.world.invariants.map((invariant) => `
    <div class="invariant-item">
      <i aria-hidden="true">◇</i>
      <strong>${escapeHtml(invariant.name)}</strong>
      <p>${escapeHtml(invariant.statement)}</p>
    </div>
  `).join("");
}

function receiptTime(receipt) {
  const date = new Date(receipt.at);
  const now = Date.now();
  const difference = Math.max(0, now - date.getTime());
  if (difference < 60_000) return "just now";
  if (difference < 3_600_000) return `${Math.floor(difference / 60_000)}m ago`;
  if (difference < 86_400_000) return `${Math.floor(difference / 3_600_000)}h ago`;
  return date.toLocaleDateString(undefined, { month: "short", day: "numeric" });
}

function renderTrace() {
  const integrity = app.world.integrity;
  elements.traceIntegrity.textContent = integrity.ok ? "The thread is intact." : "The thread has broken.";
  elements.traceSummary.textContent = integrity.ok
    ? `${integrity.receipts_checked} receipts agree on how this present came to be.`
    : integrity.errors[0] || "An unexplained discontinuity was found.";
  $(".trace-status__seal span").textContent = integrity.ok ? "✓" : "!";

  elements.receiptList.innerHTML = app.world.receipts.map((receipt) => `
    <li class="receipt receipt--${escapeHtml(receipt.kind)}">
      <div class="receipt__meta">
        <span>#${String(receipt.seq).padStart(4, "0")} · ${escapeHtml(receipt.kind)}</span>
        <time datetime="${escapeHtml(receipt.at)}">${escapeHtml(receiptTime(receipt))}</time>
      </div>
      <p>${escapeHtml(receipt.summary)}</p>
      <code>${escapeHtml(receipt.hash.slice(0, 12))} ← ${escapeHtml(receipt.previous.slice(0, 8))}</code>
    </li>
  `).join("");
  const hidden = Math.max(0, app.world.receipt_count - app.world.receipts.length);
  elements.traceFooter.textContent = hidden ? `${hidden} earlier receipts remain in the exported world.` : "Genesis is visible. Nothing earlier is hidden.";
}

function renderForecast(result) {
  const measures = ["vitality", "moisture", "diversity", "kinship"];
  const width = 360;
  const height = 140;
  const padding = 11;
  const maximumCycle = Math.max(...result.path.map((sample) => sample.cycle), 1);
  const paths = measures.map((measure) => {
    const points = result.path.map((sample) => {
      const x = padding + (sample.cycle / maximumCycle) * (width - padding * 2);
      const y = height - padding - sample.metrics[measure] * (height - padding * 2);
      return [x, y];
    });
    const commands = points.map(([x, y], index) => `${index ? "L" : "M"}${x.toFixed(1)},${y.toFixed(1)}`).join(" ");
    const [lastX, lastY] = points.at(-1);
    return `<path d="${commands}" stroke="${metricColors[measure]}" opacity=".86"/><circle cx="${lastX}" cy="${lastY}" r="2.5" fill="${metricColors[measure]}"/>`;
  }).join("");
  elements.forecastChart.innerHTML = `<svg viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="img"><title>Projected world measures</title>${paths}</svg>`;

  elements.forecastDeltas.innerHTML = measures.map((measure) => {
    const delta = result.delta[measure];
    const className = delta > 0.001 ? "is-positive" : delta < -0.001 ? "is-negative" : "";
    return `<div><span>${titleCase(measure)}</span><strong class="${className}">${percent(delta, true)}</strong></div>`;
  }).join("");

  elements.reading.classList.toggle("is-refusal", !result.can_commit);
  elements.readingMark.textContent = result.can_commit ? "◇" : "⊘";
  elements.readingLabel.textContent = result.can_commit ? "The world can carry this" : "A boundary is speaking";
  elements.rehearsalReading.textContent = result.reading;
  elements.violationList.innerHTML = result.violations.map((violation) => {
    const invariant = app.world.invariants.find((item) => item.id === violation.id);
    return `<div class="violation"><strong>${escapeHtml(invariant?.name || titleCase(violation.id))}</strong><span>${escapeHtml(violation.message)} First visible at rehearsal cycle ${violation.at_cycle}.</span></div>`;
  }).join("");

  elements.commitButton.textContent = result.can_commit ? "Commit this touch" : "Let the boundary stand";
  elements.commitButton.classList.toggle("is-refusal", !result.can_commit);
  $("#rehearsalTitle").textContent = result.can_commit ? "Before the touch becomes real" : "This future asks for another shape";
}

function showDialog(dialog) {
  if (typeof dialog.showModal === "function") dialog.showModal();
  else dialog.setAttribute("open", "");
}

async function rehearse(proposal) {
  if (app.busy) return;
  app.busy = true;
  renderLaws();
  try {
    const result = await api("/api/rehearse", {
      method: "POST",
      body: JSON.stringify({ proposal, horizon: 24 }),
    });
    app.rehearsal = result;
    renderForecast(result);
    showDialog(elements.rehearsalDialog);
  } catch (error) {
    handleError(error, "The rehearsal could not be formed.");
  } finally {
    app.busy = false;
    renderLaws();
  }
}

async function commitRehearsal() {
  if (!app.rehearsal || app.busy) return;
  app.busy = true;
  elements.commitButton.disabled = true;
  const expectedAcceptance = app.rehearsal.can_commit;
  try {
    const result = await api("/api/commit", {
      method: "POST",
      body: JSON.stringify({ ticket: app.rehearsal.ticket }),
      allowRefusal: true,
    });
    app.world = result.world;
    app.rehearsal = null;
    app.draftLaws = {};
    elements.rehearsalDialog.close();
    renderWorld({ preserveDraft: false });
    showToast(result.accepted ? "The touch entered the living world." : "The boundary stands, and its refusal was remembered.");
  } catch (error) {
    if (error.payload?.conflict) {
      elements.rehearsalDialog.close();
      showToast("The world changed while you considered it. Rehearse against the new present.", true);
      await refreshWorld();
    } else {
      handleError(error, expectedAcceptance ? "The touch could not be committed." : "The refusal could not be recorded.");
    }
  } finally {
    app.busy = false;
    elements.commitButton.disabled = false;
  }
}

async function refreshWorld({ initial = false } = {}) {
  try {
    const previousCycle = app.world?.cycle;
    const world = await api("/api/world");
    app.world = world;
    renderWorld();
    if (initial) {
      document.body.classList.add("is-ready");
      const latest = world.receipts[0];
      if (latest?.kind === "continuation" && latest.data?.cycles > 0) {
        showToast(`The world carried itself through ${latest.data.cycles} ${latest.data.cycles === 1 ? "cycle" : "cycles"} while unattended.`);
      }
    } else if (previousCycle != null && world.cycle > previousCycle) {
      showToast(`The world turned ${world.cycle - previousCycle} ${world.cycle - previousCycle === 1 ? "cycle" : "cycles"}.`);
    }
  } catch (error) {
    elements.continuity.classList.add("is-offline");
    elements.continuityText.textContent = "Thread unavailable";
    if (initial) {
      document.body.classList.add("is-ready");
      elements.worldAnswer.hidden = false;
      elements.answerText.textContent = "The material world could not be reached. Start it with bin/tendora serve, then return here.";
    }
    throw error;
  }
}

function handleError(error, fallback) {
  console.error(error);
  showToast(error.message || fallback, true);
}

function showToast(message, error = false) {
  window.clearTimeout(app.toastTimer);
  elements.toast.textContent = message;
  elements.toast.classList.toggle("is-error", error);
  elements.toast.classList.add("is-visible");
  app.toastTimer = window.setTimeout(() => elements.toast.classList.remove("is-visible"), 4200);
}

function selectTab(name, focus = false) {
  for (const tab of $$("[role='tab']")) {
    const selected = tab.dataset.tab === name;
    tab.setAttribute("aria-selected", String(selected));
    tab.tabIndex = selected ? 0 : -1;
    if (selected && focus) tab.focus();
  }
  for (const panel of $$("[role='tabpanel']")) {
    panel.hidden = panel.id !== `${name}Panel`;
  }
}

function wireEvents() {
  for (const tab of $$("[role='tab']")) {
    tab.addEventListener("click", () => selectTab(tab.dataset.tab));
    tab.addEventListener("keydown", (event) => {
      if (!["ArrowLeft", "ArrowRight"].includes(event.key)) return;
      const tabs = $$("[role='tab']");
      const direction = event.key === "ArrowRight" ? 1 : -1;
      const next = (tabs.indexOf(tab) + direction + tabs.length) % tabs.length;
      selectTab(tabs[next].dataset.tab, true);
    });
  }

  elements.placeSelect.addEventListener("change", () => setSelected(elements.placeSelect.value));
  $("#weakestButton").addEventListener("click", () => setSelected(app.world.metrics.weakest));

  for (const button of $$("[data-gesture]")) {
    button.addEventListener("click", () => {
      if (Object.keys(app.draftLaws).length) {
        selectTab("laws");
        showToast("Rehearse or return the held law changes before touching a place.");
        return;
      }
      const cell = selectedCell();
      if (!cell) return;
      rehearse({ kind: "tend", cell_id: cell.id, focus: button.dataset.gesture, amount: 0.12 });
    });
  }

  for (const label of $$(".law", elements.lawControls)) {
    const input = $("input", label);
    input.addEventListener("input", () => {
      const law = label.dataset.law;
      const value = Number(input.value);
      if (Math.abs(value - app.world.laws[law]) < 0.0001) delete app.draftLaws[law];
      else app.draftLaws[law] = value;
      renderLaws();
    });
  }

  elements.rehearseLaws.addEventListener("click", () => {
    if (Object.keys(app.draftLaws).length) rehearse({ kind: "retune", changes: app.draftLaws });
  });

  elements.commitButton.addEventListener("click", commitRehearsal);
  elements.rehearsalDialog.addEventListener("close", () => { app.rehearsal = null; });

  elements.probeForm.addEventListener("submit", async (event) => {
    event.preventDefault();
    const question = elements.probeInput.value.trim();
    if (!question || app.busy) return;
    app.busy = true;
    const button = $("button[type='submit']", elements.probeForm);
    button.disabled = true;
    try {
      const result = await api("/api/probe", { method: "POST", body: JSON.stringify({ question }) });
      app.world = result.world;
      elements.answerText.textContent = result.answer;
      elements.worldAnswer.hidden = false;
      elements.probeInput.value = "";
      renderWorld();
    } catch (error) {
      handleError(error, "The question did not reach the world.");
    } finally {
      app.busy = false;
      button.disabled = false;
    }
  });

  $("#closeAnswer").addEventListener("click", () => { elements.worldAnswer.hidden = true; });
  $("#aboutButton").addEventListener("click", () => showDialog($("#aboutDialog")));

  $("#turnButton").addEventListener("click", async () => {
    if (app.busy) return;
    app.busy = true;
    try {
      const result = await api("/api/advance", { method: "POST", body: JSON.stringify({ cycles: 1 }) });
      app.world = result.world;
      renderWorld();
      showToast("One deliberate cycle entered the receipt trail.");
    } catch (error) {
      handleError(error, "The world could not turn.");
    } finally {
      app.busy = false;
    }
  });

  $("#exportButton").addEventListener("click", () => {
    const link = document.createElement("a");
    link.href = "/api/export";
    link.download = "tendora-world.json";
    document.body.append(link);
    link.click();
    link.remove();
    showToast("A complete, portable world was prepared.");
  });

  document.addEventListener("visibilitychange", () => {
    if (!document.hidden && !app.busy && !Object.keys(app.draftLaws).length) refreshWorld().catch(() => {});
  });
}

async function begin() {
  app.map = new WorldMap($("#worldCanvas"), setSelected);
  wireEvents();
  await refreshWorld({ initial: true }).catch((error) => handleError(error, "The world is unavailable."));

  window.setInterval(() => {
    const dialogOpen = $("dialog[open]");
    if (!document.hidden && !app.busy && !dialogOpen && !Object.keys(app.draftLaws).length) {
      refreshWorld().catch(() => {});
    }
  }, 30_000);

  if ("serviceWorker" in navigator) {
    navigator.serviceWorker.register("/sw.js").catch(() => {});
  }
}

begin();

