  padding: 11px 12px;
  border-right: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.place-measures span {
  color: var(--ink-faint);
  font-size: 8px;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.place-measures strong {
  grid-column: 2;
  grid-row: 1 / 3;
  color: var(--ink-soft);
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 400;
}

.place-measures i {
  position: relative;
  height: 2px;
  background: rgba(255, 255, 255, 0.07);
}

.place-measures b {
  position: absolute;
  inset: 0 auto 0 0;
  width: 0;
  background: var(--sage);
  transition: width 500ms ease;
}

.gesture-intro {
  margin: 24px 0 13px;
}

.gesture-intro p,
.panel-intro p,
.trace-status p {
  margin: 7px 0 0;
  color: var(--ink-faint);
  font-family: var(--serif);
  font-size: 12px;
  line-height: 1.45;
}

.gesture-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  border-top: 1px solid var(--line);
  border-left: 1px solid var(--line);
}

.gesture-grid button {
  min-height: 70px;
  display: grid;
  grid-template-columns: 30px 1fr;
  align-items: center;
  gap: 5px;
  padding: 10px;
  border: 0;
  border-right: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  background: transparent;
  text-align: left;
  transition: background 160ms, color 160ms;
}

.gesture-grid button:hover {
  background: rgba(170, 191, 149, 0.045);
}

.gesture-glyph {
  color: var(--sage);
  font-family: var(--serif);
  font-size: 20px;
  text-align: center;
}

.gesture-grid button > span:last-child { display: flex; flex-direction: column; gap: 3px; }
.gesture-grid strong { font-family: var(--serif); font-size: 13px; font-weight: 400; }
.gesture-grid small { color: var(--ink-faint); font-size: 8px; line-height: 1.25; }

.panel-intro {
  padding-bottom: 20px;
  border-bottom: 1px solid var(--line);
}

.panel-intro h3 {
  margin-top: 7px;
  line-height: 1.2;
}

.panel-intro p {
  max-width: 340px;
  font-size: 13px;
}

.law-controls {
  padding-top: 4px;
}

.law {
  display: block;
  padding: 15px 0 13px;
  border-bottom: 1px solid var(--line);
}

.law > span {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
}

.law strong {
  font-family: var(--serif);
  font-size: 14px;
  font-weight: 400;
}

.law output {
  color: var(--sage);
  font-family: var(--mono);
  font-size: 9px;
}

.law small {
  display: block;
  margin-top: 3px;
  color: var(--ink-faint);
  font-size: 9px;
}

.law input {
  width: 100%;
  height: 12px;
  margin: 9px 0 0;
  appearance: none;
  background: transparent;
}

.law input::-webkit-slider-runnable-track {
  height: 2px;
  background: linear-gradient(90deg, var(--sage) var(--range-fill, 50%), rgba(255, 255, 255, 0.09) var(--range-fill, 50%));
}

.law input::-webkit-slider-thumb {
  width: 10px;
  height: 10px;
  margin-top: -4px;
  appearance: none;
  border: 1px solid var(--sage-bright);
  border-radius: 50%;
  background: var(--ground-raised);
  box-shadow: 0 0 0 3px rgba(170, 191, 149, 0.07);
}

.law input::-moz-range-track {
  height: 2px;
  background: rgba(255, 255, 255, 0.09);
}

.law input::-moz-range-progress { height: 2px; background: var(--sage); }
.law input::-moz-range-thumb { width: 9px; height: 9px; border: 1px solid var(--sage-bright); border-radius: 50%; background: var(--ground-raised); }

.law.is-changed strong::after {
  content: " •";
  color: var(--amber);
}

.law--reserve output { color: var(--amber); }

.draft-action {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 18px;
  padding: 12px 12px 12px 14px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.015);
}

.draft-action > div { display: flex; flex-direction: column; gap: 3px; }
.draft-action small { color: var(--ink-faint); font-size: 8px; text-transform: uppercase; letter-spacing: 0.1em; }
.draft-action strong { font-family: var(--serif); font-size: 12px; font-weight: 400; }

.draft-action button {
  height: 35px;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 0 12px;
  border: 1px solid rgba(170, 191, 149, 0.28);
  background: rgba(170, 191, 149, 0.06);
  color: var(--sage-bright);
  font-size: 8px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.draft-action button:disabled {
  opacity: 0.3;
  cursor: default;
}

.invariants {
  margin-top: 12px;
  border: 1px solid var(--line);
}

.invariants summary {
  display: flex;
  justify-content: space-between;
  padding: 12px 13px;
  list-style: none;
  color: var(--ink-soft);
  font-family: var(--serif);
  font-size: 11px;
}

.invariants summary::-webkit-details-marker { display: none; }
.invariants summary small { color: var(--ink-faint); font-family: var(--sans); font-size: 8px; letter-spacing: 0.08em; text-transform: uppercase; }
.invariants[open] summary { border-bottom: 1px solid var(--line); }

.invariant-item {
  display: grid;
  grid-template-columns: 15px 1fr;
  gap: 6px 8px;
  padding: 10px 12px;
  border-bottom: 1px solid var(--line);
}

.invariant-item:last-child { border-bottom: 0; }
.invariant-item > i { color: var(--sage); font-size: 9px; font-style: normal; }
.invariant-item strong { font-family: var(--serif); font-size: 11px; font-weight: 400; }
.invariant-item p { grid-column: 2; margin: -3px 0 0; color: var(--ink-faint); font-size: 8px; line-height: 1.4; }

.trace-status {
  display: grid;
  grid-template-columns: 52px 1fr;
  align-items: center;
  gap: 13px;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--line);
}

.trace-status__seal {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  border: 1px solid rgba(170, 191, 149, 0.36);
  border-radius: 50%;
  box-shadow: inset 0 0 0 6px rgba(170, 191, 149, 0.025);
}

.trace-status__seal span { color: var(--sage); font-size: 13px; }
.trace-status h3 { margin-top: 5px; font-size: 18px; }

.trace-key {
  display: flex;
  flex-wrap: wrap;
  gap: 11px;
  padding: 12px 0;
  color: var(--ink-faint);
  font-size: 7px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.trace-key span { display: flex; align-items: center; gap: 4px; }
.receipt-color { width: 5px; height: 5px; border-radius: 50%; background: var(--ink-faint); }
.receipt-color--commitment { background: var(--sage); }
.receipt-color--probe { background: var(--water); }
.receipt-color--continuation { background: var(--amber); }
.receipt-color--refusal { background: var(--rose); }

.receipt-list {
  position: relative;
  margin: 0;
  padding: 0 0 0 18px;
  list-style: none;
}

.receipt-list::before {
  content: "";
  position: absolute;
  left: 3px;
  top: 8px;
  bottom: 7px;
  border-left: 1px solid var(--line);
}

.receipt {
  position: relative;
  padding: 0 0 17px 4px;
}

.receipt::before {
  content: "";
  position: absolute;
  left: -18px;
  top: 5px;
  width: 6px;
  height: 6px;
  border: 2px solid var(--panel);
  border-radius: 50%;
  background: var(--ink-faint);
  box-shadow: 0 0 0 1px var(--line-strong);
}

.receipt--commitment::before { background: var(--sage); }
.receipt--probe::before { background: var(--water); }
.receipt--continuation::before,
.receipt--turn::before { background: var(--amber); }
.receipt--refusal::before { background: var(--rose); }

.receipt__meta {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 4px;
  color: var(--ink-faint);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.receipt p {
  margin: 0;
  color: var(--ink-soft);
  font-family: var(--serif);
  font-size: 11px;
  line-height: 1.4;
}

.receipt code {
  display: inline-block;
  margin-top: 4px;
  color: #626a60;
  font-family: var(--mono);
  font-size: 7px;
}

.trace-footer {
  margin: 5px 0 0 18px;
  color: var(--ink-faint);
  font-size: 8px;
}

dialog {
  padding: 0;
  border: 1px solid rgba(191, 203, 174, 0.22);
  background: #111813;
  color: var(--ink);
  box-shadow: 0 36px 100px rgba(0, 0, 0, 0.68);
}

dialog::backdrop {
  background: rgba(4, 7, 5, 0.78);
  backdrop-filter: blur(7px);
}

dialog[open] { animation: dialog-in 260ms ease both; }

@keyframes dialog-in {
  from { opacity: 0; transform: translateY(10px) scale(0.99); }
}

.rehearsal {
  width: min(760px, calc(100vw - 32px));
  max-height: calc(100vh - 32px);
}

.dialog-frame { margin: 0; }

.dialog-header {
  min-height: 82px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 22px;
  border-bottom: 1px solid var(--line);
}

.dialog-header small { display: block; margin-bottom: 5px; }
.dialog-header h2 { margin: 0; font-family: var(--serif); font-size: 22px; font-weight: 400; }

.dialog-close {
  width: 34px;
  height: 34px;
  border: 1px solid var(--line);
  background: transparent;
  color: var(--ink-faint);
  font-size: 21px;
  font-weight: 200;
  line-height: 1;
}

.dialog-close:hover { color: var(--ink); border-color: var(--line-strong); }

.rehearsal-body {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  min-height: 300px;
}

.forecast {
  padding: 24px;
  border-right: 1px solid var(--line);
}

.forecast__header {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 9px;
  color: var(--ink-faint);
  font-size: 8px;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.forecast__header i { border-top: 1px solid var(--line); }

.forecast-chart {
  height: 150px;
  margin: 15px 0 18px;
  border: 1px solid var(--line);
  background:
    linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.02) 1px, transparent 1px);
  background-size: 100% 25%, 16.66% 100%;
}

.forecast-chart svg { display: block; width: 100%; height: 100%; overflow: visible; }
.forecast-chart path { fill: none; stroke-width: 1.4; vector-effect: non-scaling-stroke; }
.forecast-chart circle { stroke: #111813; stroke-width: 1.4; vector-effect: non-scaling-stroke; }

.forecast-deltas {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1px;
  background: var(--line);
  border: 1px solid var(--line);
}

.forecast-deltas > div {
  display: flex;
  justify-content: space-between;
  padding: 9px 10px;
  background: #111813;
}

.forecast-deltas span { color: var(--ink-faint); font-size: 8px; text-transform: uppercase; letter-spacing: 0.07em; }
.forecast-deltas strong { font-family: var(--mono); font-size: 9px; font-weight: 400; }
.forecast-deltas strong.is-positive { color: var(--sage); }
.forecast-deltas strong.is-negative { color: var(--rose); }

.reading {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 28px;
  background: rgba(255, 255, 255, 0.012);
}

.reading__mark {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  margin-bottom: 18px;
  border: 1px solid var(--line-strong);
  border-radius: 50%;
  color: var(--sage);
  font-size: 18px;
}

.reading.is-refusal .reading__mark { color: var(--rose); border-color: rgba(196, 119, 105, 0.35); }
.reading.is-refusal > small { color: var(--rose); }

.reading p {
  margin: 9px 0 0;
  color: #d2d0c4;
  font-family: var(--serif);
  font-size: 16px;
  line-height: 1.5;
}

.violation-list { margin-top: 16px; }

.violation {
  padding: 9px 0;
  border-top: 1px solid var(--line);
}

.violation strong { display: block; color: var(--rose); font-size: 9px; font-weight: 500; text-transform: uppercase; letter-spacing: 0.08em; }
.violation span { display: block; margin-top: 3px; color: var(--ink-faint); font-size: 9px; line-height: 1.35; }

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 9px;
  padding: 15px 20px;
  border-top: 1px solid var(--line);
}

.primary-button,
.secondary-button {
  min-height: 39px;
  padding: 0 17px;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.secondary-button { border: 1px solid var(--line); background: transparent; color: var(--ink-faint); }
.secondary-button:hover { border-color: var(--line-strong); color: var(--ink); }

.primary-button {
  border: 1px solid rgba(179, 201, 157, 0.33);
  background: rgba(170, 191, 149, 0.11);
  color: var(--sage-bright);
}

.primary-button:hover { background: rgba(170, 191, 149, 0.17); }
.primary-button.is-refusal { border-color: rgba(196, 119, 105, 0.3); background: rgba(196, 119, 105, 0.08); color: #db9589; }

.about {
  width: min(650px, calc(100vw - 32px));
  max-height: calc(100vh - 32px);
}

.about__frame {
  position: relative;
  padding: 42px 46px;
}

.about__frame > .dialog-close { position: absolute; top: 16px; right: 16px; }
.about__frame > .seed-mark { margin-bottom: 26px; }
.about__frame > small { display: block; color: var(--sage); }

.about__frame h2 {
  margin: 10px 0 18px;
  font-family: var(--serif);
  font-size: 34px;
  font-weight: 400;
  line-height: 1.04;
}

.about__frame > p {
  max-width: 540px;
  color: var(--ink-soft);
  font-family: var(--serif);
  font-size: 16px;
  line-height: 1.55;
}

.about__columns {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin: 28px 0 30px;
  padding: 22px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.about__columns p { margin: 0; color: var(--ink-faint); font-size: 10px; line-height: 1.5; }
.about__columns strong { color: var(--ink-soft); font-family: var(--serif); font-size: 13px; font-weight: 400; }

.toast {
  position: fixed;
  z-index: 110;
  left: 50%;
  bottom: 22px;
  max-width: calc(100vw - 32px);
  padding: 10px 15px;
  transform: translate(-50%, 20px);
  border: 1px solid var(--line-strong);
  background: rgba(19, 27, 22, 0.96);
  color: var(--ink-soft);
  box-shadow: 0 10px 35px rgba(0, 0, 0, 0.4);
  font-size: 10px;
  opacity: 0;
  visibility: hidden;
  transition: opacity 180ms, transform 180ms, visibility 180ms;
}

.toast.is-visible { opacity: 1; visibility: visible; transform: translate(-50%, 0); }
.toast.is-error { border-color: rgba(196, 119, 105, 0.4); color: #db9589; }

.noscript {
  position: fixed;
  z-index: 200;
  inset: 0;
  display: grid;
  place-content: center;
  padding: 30px;
  background: var(--ground);
  color: var(--ink);
  text-align: center;
}

@media (max-width: 1120px) {
  :root { --panel-width: 390px; }
  .metrics-ribbon { grid-template-columns: 1fr 1fr; width: 340px; }
  .metric:nth-child(2) { border-right: 0; }
  .metric:nth-child(-n + 2) { border-bottom: 1px solid var(--line); }
  .metrics-ribbon { bottom: 100px; }
}

@media (max-height: 760px) and (min-width: 901px) {
  .workbench__header { height: 78px; padding-top: 12px; padding-bottom: 11px; }
  .workbench__header h2 { font-size: 16px; }
  .panel { height: calc(100% - 126px); padding-top: 18px; }
  .place-measures > div { padding-top: 8px; padding-bottom: 8px; }
  .gesture-intro { margin-top: 17px; }
  .gesture-grid button { min-height: 58px; }
}

@media (max-width: 900px) {
  body { overflow: auto; }
  .topbar { position: sticky; top: 0; grid-template-columns: 1fr auto; }
  .continuity { display: none; }
  .shell { height: auto; min-height: calc(100vh - var(--header-height)); grid-template-columns: 1fr; }
  .world-stage { height: max(570px, calc(100vh - var(--header-height))); }
  .workbench { min-height: 720px; border-top: 1px solid var(--line); border-left: 0; overflow: visible; }
  .panel { height: auto; min-height: 580px; overflow: visible; }
  .stage-vignette { box-shadow: inset 0 -80px 100px rgba(6,9,7,.5); }
}

@media (max-width: 620px) {
  :root { --header-height: 64px; }
  .topbar { padding: 0 14px; }
  .identity__words small { display: none; }
  .wide-label { display: none; }
  .icon-button { width: 34px; justify-content: center; padding: 0; }
  .world-stage { height: 620px; }
  .stage-coordinate--top { left: 16px; top: 17px; }
  .world-time { right: 16px; top: 16px; }
  .metrics-ribbon { left: 16px; bottom: 104px; width: calc(100% - 32px); }
  .metric { padding-left: 10px; padding-right: 10px; }
  .question-dock { left: 16px; right: 16px; bottom: 25px; }
  .question-dock button { padding: 0 13px; }
  .question-dock button span { display: none; }
  .question-dock input { font-size: 14px; }
  .workbench__header, .panel { padding-left: 18px; padding-right: 18px; }
  .gesture-grid { grid-template-columns: 1fr; }
  .gesture-grid button { min-height: 58px; }
  .rehearsal-body { grid-template-columns: 1fr; }
  .forecast { border-right: 0; border-bottom: 1px solid var(--line); }
  .reading { min-height: 210px; }
  .dialog-header h2 { font-size: 18px; }
  .dialog-actions { justify-content: stretch; }
  .dialog-actions button { flex: 1; }
  .about__frame { padding: 34px 25px 28px; }
  .about__frame h2 { font-size: 29px; }
  .about__columns { grid-template-columns: 1fr; gap: 14px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

const CACHE = "tendora-instrument-v3";
const SHELL = ["/", "/index.html", "/styles.css", "/app.js", "/icon.svg", "/manifest.webmanifest"];

self.addEventListener("install", (event) => {
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(SHELL)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((key) => key !== CACHE).map((key) => caches.delete(key))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener("fetch", (event) => {
  const url = new URL(event.request.url);
  if (url.origin !== self.location.origin || url.pathname.startsWith("/api/")) return;
  if (event.request.method !== "GET") return;
  event.respondWith(
    caches.match(event.request).then((cached) => cached || fetch(event.request).then((response) => {
      if (response.ok) {
        const copy = response.clone();
        caches.open(CACHE).then((cache) => cache.put(event.request, copy));
      }
      return response;
    })),
  );
});
